import{i as e}from"./index-xqFC_Jp1.js";var t=e({food:()=>n}),n={boston:{eateries:[{id:`union-oyster-house`,name:`Union Oyster House`,area:`Downtown`,lat:42.36122,lng:-71.05688,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[35,70],order:[{name:`New England clam chowder`,note:`Creamy chowder thick with clams and potatoes`,wiki:`Clam chowder`},{name:`Oysters from the raw bar`,note:`Shucked to order at the original semicircular oyster bar`},{name:`Broiled scrod`,note:`Flaky young cod under buttery crumbs, an old Boston staple`}],why:`Open since 1826 on the Freedom Trail, it claims to be America's oldest restaurant, with creaky wooden booths and the same oyster bar used for two centuries.`,tip:`Grab a stool at the downstairs oyster bar for chowder and a dozen oysters rather than a full sit-down meal.`,praise:[`Atmospheric historic rooms and oyster bar`,`Hearty chowder and fresh shucked oysters`,`An easy stop between Freedom Trail sites`],watchOut:`Touristy and pricey for traditional cooking; the history is the main draw.`,reservation:`recommended`,reservationNote:`Book dinner online, especially in summer and autumn; the oyster bar is first come, first served`},{id:`neptune-oyster`,name:`Neptune Oyster`,area:`North End`,lat:42.36332,lng:-71.05558,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[45,90],order:[{name:`Warm buttered lobster roll`,note:`A brioche bun overflowing with hot lobster and drawn butter`,wiki:`Lobster roll`},{name:`Raw oysters`,note:`A long daily list of New England and other oysters`},{name:`Fried clams`,note:`Crisp whole-belly clams`,wiki:`Fried clams`}],why:`A tiny marble-countered oyster bar whose hot buttered lobster roll is famous across the country, with an excellent raw bar since 1996.`,tip:`Arrive before opening or mid-afternoon to shorten the queue; the lobster roll is priced at market rate.`,praise:[`Generous, buttery lobster roll`,`Superb, very fresh raw bar`,`Cosy, buzzing little room`],watchOut:`Long queues for very few seats, and the bill climbs fast.`,reservation:`walk-in`,reservationNote:`No reservations; queue in person, ideally at opening or mid-afternoon`},{id:`pizzeria-regina-north-end`,name:`Pizzeria Regina`,area:`North End`,lat:42.36535,lng:-71.05698,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[15,30],order:[{name:`Giambotta`,note:`The everything pizza: sausage, pepperoni, salami, peppers, onion and mushroom`},{name:`Margherita`,note:`Tomato, mozzarella and basil on a thin, charred crust`,wiki:`Pizza Margherita`}],why:`The original 1926 brick-oven pizzeria tucked down a North End side street, still turning out thin, blistered pies in its old wooden-booth dining room.`,tip:`Go just after opening or mid-afternoon; ignore the chain kiosks elsewhere, as this original is the one to visit.`,praise:[`Crisp, smoky brick-oven crust`,`Old-school North End character`,`Good value for a big shared pie`],watchOut:`Long weekend waits and gruff, rushed service.`,reservation:`walk-in`,reservationNote:`No bookings at the original; join the line outside`},{id:`mikes-pastry`,name:`Mike's Pastry`,area:`North End`,lat:42.36423,lng:-71.05425,kind:`dessert`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[5,12],order:[{name:`Ricotta cannoli`,price:6,note:`A big crisp shell filled to order with sweet ricotta`,wiki:`Cannoli`},{name:`Florentine cannoli`,note:`Lacy almond-caramel shell with cream filling`},{name:`Lobster tail pastry`,note:`Flaky shell pastry filled with cream`}],why:`A North End institution since 1946, with a huge range of cannoli flavours sent out in the white string-tied boxes you see all over town.`,tip:`Take your box to the waterfront or eat on Hanover Street; it is busiest after dinner, when the North End restaurants empty out.`,praise:[`Enormous choice of cannoli flavours`,`A fun, bustling North End ritual`,`Cheap sweet treat to take away`],watchOut:`A scrum rather than a queue at busy times, and locals often prefer the crisper shells at rivals nearby.`,reservation:`walk-in`,reservationNote:`Counter service only; jostle to the counter and point`},{id:`row-34-fort-point`,name:`Row 34`,area:`Seaport`,lat:42.34912,lng:-71.04783,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,90],order:[{name:`Raw bar oysters`,note:`Island Creek and other local oysters, shucked to order`},{name:`Warm or cold lobster roll`,note:`Lobster on a toasted bun, dressed with butter or mayo`,wiki:`Lobster roll`},{name:`Clam chowder`,note:`A lighter, brothier take on the classic`,wiki:`Clam chowder`}],why:`The Island Creek Oyster team's brick-walled seafood hall in a 1908 warehouse, celebrated for its oyster list and craft beer since 2013.`,tip:`Sit at the bar for oysters and a beer; it validates parking for evening diners.`,praise:[`Pristine oysters and creative crudo`,`Excellent beer list to match`,`Lively, industrial-chic room`],watchOut:`Loud at peak times, and oysters add up quickly.`,reservation:`recommended`,reservationNote:`Book dinner online a few days ahead; bar seats are kept for walk-ins`},{id:`flour-bakery-south-end`,name:`Flour Bakery + Cafe`,area:`South End`,lat:42.33911,lng:-71.07714,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[6,15],order:[{name:`Sticky bun`,note:`Gooey caramel-pecan bun, the house signature`},{name:`Roast lamb sandwich`,note:`Lamb with tomato chutney and goat cheese on fresh bread`},{name:`Boston cream pie`,note:`The bakery's own take on the city's classic cake`,wiki:`Boston cream pie`}],why:`Joanne Chang's original South End bakery-cafe, open since 2000 and loved for sticky buns, pastries and generous sandwiches.`,tip:`Weekend mornings bring a line; a weekday lunch is calmer, and there are other branches around the city.`,praise:[`Outstanding sticky buns and pastries`,`Fresh, generous sandwiches`,`Bright, friendly neighbourhood cafe`],reservation:`walk-in`,reservationNote:`Order at the counter; no bookings`},{id:`sullivans-castle-island`,name:`Sullivan's Castle Island`,area:`South Boston`,lat:42.3372,lng:-71.013,kind:`casual`,meals:[`lunch`,`dinner`],spend:[6,15],order:[{name:`Hot dog`,note:`A cheap, classic grilled dog in a soft bun`},{name:`Fried clams`,note:`Crisp fried clams with tartar sauce`,wiki:`Fried clams`},{name:`Lobster roll`,note:`A simple, cold lobster roll at a fair price`,wiki:`Lobster roll`}],why:`A beloved seaside snack stand by Fort Independence, run by the same family since 1951, serving cheap hot dogs and fried seafood to generations of locals.`,tip:`Seasonal: open from late February to around late November. Walk the Pleasure Bay loop after eating.`,praise:[`Bargain prices by the sea`,`Classic, no-fuss clam-shack food`,`A true local tradition`],watchOut:`Closed in winter, and outdoor seating only on cold or windy days.`,reservation:`walk-in`,reservationNote:`Walk-up window; lines move fast`},{id:`pinocchios-pizza-harvard-square`,name:`Pinocchio's Pizza & Subs`,area:`Cambridge`,lat:42.37199,lng:-71.12052,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[5,12],order:[{name:`Sicilian tomato basil slice`,note:`A thick, square Sicilian slice with fresh tomato and basil`,wiki:`Sicilian pizza`},{name:`Steak and cheese sub`,note:`Shaved steak and melted cheese in a long roll`}],why:`A Harvard Square slice shop for decades, adored by generations of students for thick, square Sicilian slices at student prices.`,tip:`Open late, so it is perfect after an evening in Harvard Square; slices are reheated to order.`,praise:[`Fluffy, crisp-bottomed Sicilian slices`,`Cheap and filling`,`Open late most nights`],watchOut:`Tiny and cramped, with few seats at peak times.`,reservation:`walk-in`,reservationNote:`Order at the counter; no bookings`}],dishes:{"New England clam chowder":{price:[7,14],wiki:`Clam chowder`},"Lobster roll":{price:[28,45],wiki:`Lobster roll`},"Fried clams":{price:[20,35],wiki:`Fried clams`},"Raw oysters":{price:[18,30]},Cannoli:{price:[4,7],wiki:`Cannoli`},"Boston cream pie":{price:[6,12],wiki:`Boston cream pie`}}}},r=e({food:()=>i}),i={chicago:{eateries:[{id:`lou-malnatis-river-north`,name:`Lou Malnati's Pizzeria`,area:`River North`,lat:41.8904,lng:-87.6339,kind:`casual`,meals:[`lunch`,`dinner`],spend:[20,35],order:[{name:`The Malnati Chicago Classic`,price:24,note:`Deep dish with a sausage patty, mozzarella and chunky tomato on a buttercrust`,wiki:`Deep-dish pizza`},{name:`Deep dish with spinach and mushroom`,note:`A vegetarian deep dish under a layer of tomato sauce`},{name:`Malnati salad`,price:12,note:`Romaine with salami, mushrooms, tomato and the sweet house vinaigrette`}],why:`A family pizzeria founded in 1971 whose flaky, buttery deep dish is the version many Chicagoans swear by; River North is a handy downtown branch.`,tip:`Deep dish takes 30 to 45 minutes to bake, so order as soon as you sit down; a small pizza feeds two.`,praise:[`Buttery, flaky crust that stays crisp`,`Bright, chunky tomato sauce on top`,`A reliable classic in a friendly setting`],watchOut:`Long waits at dinner, and the bake time adds another 40 minutes.`,reservation:`recommended`,reservationNote:`Join the waitlist online or call ahead at busy times; lunch is usually a walk-in`},{id:`pequods-pizza`,name:`Pequod's Pizza`,area:`Lincoln Park`,lat:41.9219,lng:-87.6644,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[15,30],order:[{name:`Pan pizza with sausage`,note:`Pan pizza ringed by a blackened, caramelised cheese crust`,wiki:`Deep-dish pizza`},{name:`Pepperoni pan pizza`,note:`The same caramel-edged crust with crisp-cupped pepperoni`}],why:`A neighbourhood bar-pizzeria famous for pan pizza with a burnt-cheese halo around the edge, a cult favourite since the 1970s.`,tip:`Expect a wait at peak dinner hours; open late, so a 9pm visit is often easier.`,praise:[`The crunchy, caramelised cheese crust`,`Generous toppings and lots of sausage`,`Unpretentious sports-bar vibe`],watchOut:`Busy and loud, with long waits for a table on weekends.`,reservation:`walk-in`,reservationNote:`Mostly first come, first served; put your name down and order your pizza while you wait`},{id:`portillos-river-north`,name:`Portillo's`,area:`River North`,lat:41.8934,lng:-87.6317,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[9,18],order:[{name:`Chicago-style hot dog`,price:5,note:`All-beef dog with mustard, relish, onion, tomato, pickle, sport peppers, celery salt`,wiki:`Chicago-style hot dog`},{name:`Italian beef, dipped, with hot peppers`,price:10,note:`Thin-sliced roast beef in a soaked roll with spicy giardiniera`,wiki:`Italian beef`},{name:`Chocolate cake shake`,price:6,note:`A slice of chocolate cake blended into a milkshake`}],why:`A Chicago hot dog and beef chain that began as a trailer in 1963; the big River North branch is a fun, fast way to try the classics.`,tip:`Order at the counter and listen for your number; ask for the beef dipped and hot if you like it messy and spicy.`,praise:[`Classic Chicago dogs and beefs in one stop`,`Fast and cheap even when packed`,`The famous chocolate cake shake`],watchOut:`A busy chain, so locals will point you to smaller stands for the best beef.`,reservation:`walk-in`,reservationNote:`Counter service, no bookings; lines move fast`},{id:`als-number-1-italian-beef-taylor-street`,name:`Al's #1 Italian Beef`,area:`Little Italy (Taylor Street)`,lat:41.8693,lng:-87.6547,kind:`casual`,meals:[`lunch`,`dinner`],spend:[10,16],order:[{name:`Italian beef, wet, with hot giardiniera`,price:11,note:`Garlicky shaved beef in a juice-soaked roll with spicy pickled vegetables`,wiki:`Italian beef`},{name:`Combo (beef and sausage)`,price:13,note:`Italian beef with a charred Italian sausage in the same roll`},{name:`Fresh-cut fries`,price:4,note:`Thick fries cut on site`}],why:`The original Taylor Street stand of a family business dating from 1938, still serving beef sandwiches the old way at a stand-up counter.`,tip:`Eat it standing at the counter in the Italian stance, leaning forward so the juice misses your shoes.`,praise:[`Juicy, peppery beef with real garlic punch`,`Old-school Little Italy character`,`Quick and cheap`],watchOut:`Very little seating, and a wet beef gets messy fast.`,reservation:`walk-in`,reservationNote:`Order at the counter; no bookings`},{id:`superdawg-drive-in`,name:`Superdawg Drive-In`,area:`Norwood Park`,lat:41.997,lng:-87.7874,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[8,14],order:[{name:`Superdawg`,price:8,note:`All-beef dog with the works and a pickled green tomato, in a box with fries`,wiki:`Chicago-style hot dog`},{name:`Whoopskidawg`,note:`Grilled Polish sausage with grilled onions and hot peppers`},{name:`Chocolate shake`,note:`Thick, old-fashioned milkshake`}],why:`A 1948 carhop drive-in topped by two giant hot dog mascots on the roof, still run by the founding family.`,tip:`Park under the canopy and order from the speaker for carhop service, or eat inside; it is a 30-minute drive northwest of downtown.`,praise:[`Retro carhop experience with real charm`,`Snappy dogs served with crinkle fries`,`A fun detour for families`],watchOut:`Far from the centre and awkward without a car.`,reservation:`walk-in`,reservationNote:`Drive-in and counter service; no bookings`},{id:`lou-mitchells`,name:`Lou Mitchell's`,area:`West Loop`,lat:41.8783,lng:-87.6415,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[14,25],order:[{name:`Double-yolk omelette with skillet potatoes`,price:16,note:`Fluffy omelette served in its skillet with crisp potatoes`},{name:`Greek toast and pancakes`,note:`Thick toast and buttermilk pancakes, diner classics`}],why:`A diner near Union Station open since 1923, billed as the first stop on Route 66, with free doughnut holes for those in line.`,tip:`Breakfast and lunch only; go on a weekday morning or expect a queue on weekends.`,praise:[`Huge, fluffy omelettes`,`Warm, old-school diner service`,`Little welcome treats while you wait`],watchOut:`Weekend queues out the door.`,reservation:`walk-in`,reservationNote:`No bookings; join the line, which moves steadily`},{id:`girl-and-the-goat`,name:`Girl & the Goat`,area:`West Loop`,lat:41.8841,lng:-87.6479,kind:`restaurant`,meals:[`dinner`],spend:[60,100],order:[{name:`Wood-oven roasted pig face`,note:`Crispy braised pork with a sunny egg and potato stix`},{name:`Goat empanadas`,note:`Pastries filled with spiced goat`},{name:`Sautéed green beans with fish sauce vinaigrette`,note:`Blistered beans with cashews in a punchy, sweet dressing`}],why:`Stephanie Izard's bold, shareable small plates have made this Randolph Street restaurant a West Loop anchor since 2010.`,tip:`Order four to six plates for two people to share; the bar takes walk-ins.`,praise:[`Bold, playful flavours on every plate`,`Lively, warm room`,`Knowledgeable, friendly staff`],watchOut:`Loud room, and small plates add up quickly.`,reservation:`recommended`,reservationNote:`Book a few weeks ahead for prime weekend tables; bar seating is walk-in`},{id:`frontera-grill`,name:`Frontera Grill`,area:`River North`,lat:41.8904,lng:-87.6311,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[35,60],order:[{name:`Mole of the day`,note:`A rich, complex regional Mexican sauce over meat or vegetables`,wiki:`Mole (sauce)`},{name:`Guacamole and chips`,note:`Freshly made, chunky guacamole`,wiki:`Guacamole`},{name:`Carne asada a la oaxaqueña`,note:`Grilled steak in the Oaxacan style with black beans`}],why:`Rick Bayless's 1987 restaurant brought regional Mexican cooking to American attention, and it remains a colourful, lively favourite.`,tip:`Lunch and weekend brunch are easier to book; margaritas here are famously good.`,praise:[`Deep, layered moles and salsas`,`Vibrant room full of Mexican folk art`,`Excellent margaritas`],watchOut:`Pricey for Mexican food, and dinner waits are long without a booking.`,reservation:`recommended`,reservationNote:`Book dinner online a week or two ahead; some tables are kept for walk-ins`}],dishes:{"Deep-dish pizza":{price:[20,35],wiki:`Deep-dish pizza`},"Italian beef sandwich":{price:[9,14],wiki:`Italian beef`},"Chicago-style hot dog":{price:[4,8],wiki:`Chicago-style hot dog`},"Tavern-style thin-crust pizza":{price:[15,28],wiki:`Tavern-style pizza`},"Maxwell Street Polish":{price:[5,9],wiki:`Maxwell Street Polish`},Jibarito:{price:[10,15],wiki:`Jibarito`}}}},a=e({food:()=>o}),o={honolulu:{eateries:[{id:`helenas-hawaiian-food`,name:`Helena's Hawaiian Food`,area:`Kalihi`,lat:21.33058,lng:-157.86655,kind:`casual`,meals:[`lunch`,`dinner`],spend:[15,30],order:[{name:`Pipikaula short ribs`,note:`Dried, salted short ribs fried crisp, the house signature`},{name:`Kalua pig`,localName:`Kālua puaʻa`,note:`Smoky shredded pork, traditionally cooked underground`,wiki:`Kālua`},{name:`Laulau`,note:`Pork and butterfish steamed in taro and ti leaves`}],why:`A tiny family-run Hawaiian diner open since 1946, honoured with a James Beard America's Classics award for its traditional island cooking.`,tip:`Open Tuesday to Friday only; come early, as favourites sell out, and order a set menu to share several dishes.`,praise:[`Authentic, homestyle Hawaiian food`,`Crispy, salty pipikaula ribs`,`Warm, old-fashioned family welcome`],watchOut:`Short opening days and hours, and dishes run out by mid-afternoon.`,reservation:`walk-in`,reservationNote:`No bookings; put your name down at the door and wait for a table`},{id:`ono-seafood`,name:`Ono Seafood`,area:`Kapahulu`,lat:21.2864,lng:-157.8145,kind:`casual`,meals:[`lunch`],spend:[12,20],order:[{name:`Shoyu ahi poke bowl`,note:`Fresh ahi cubes in soy and sesame over warm rice`,wiki:`Poke (dish)`},{name:`Spicy ahi poke`,note:`Ahi in a creamy, chilli-spiked mayo dressing`},{name:`Tako poke`,note:`Tender octopus poke`}],why:`A no-frills counter on Kapahulu Avenue since 1995, widely seen as one of the best places on Oʻahu for fresh, simply dressed poke.`,tip:`Take your bowl to Kapiʻolani Park or the beach, as seating is minimal; go before mid-afternoon, when it can sell out.`,praise:[`Very fresh fish, not drowned in sauce`,`Generous bowls at fair prices`,`Quick, friendly counter service`],watchOut:`Only a couple of tables, and lines form at lunchtime.`,reservation:`walk-in`,reservationNote:`Order at the counter; no bookings`},{id:`leonards-bakery`,name:`Leonard's Bakery`,area:`Kapahulu`,lat:21.28477,lng:-157.8132,kind:`bakery`,meals:[`breakfast`,`lunch`,`dinner`],spend:[4,10],order:[{name:`Original malasada`,price:2,note:`Hot, fluffy Portuguese doughnut rolled in sugar`,wiki:`Malassada`},{name:`Haupia-filled malasada`,note:`Filled with coconut custard`},{name:`Li hing malasada`,note:`Dusted with sweet-sour dried plum powder`}],why:`The bakery that made malasadas an island craze when it opened in 1952, still frying them to order under its retro neon sign.`,tip:`Order a mixed half dozen and eat them hot in the car park; filled ones are made to order.`,praise:[`Light, airy malasadas served hot`,`Fun flavours and fillings`,`Cheap, classic local treat`],watchOut:`Queues and a tiny, busy car park at peak times.`,reservation:`walk-in`,reservationNote:`Counter service; the line moves quickly`},{id:`rainbow-drive-in`,name:`Rainbow Drive-In`,area:`Kapahulu`,lat:21.2756,lng:-157.813,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[9,16],order:[{name:`Loco moco`,note:`Burger patty and fried egg on rice under brown gravy`,wiki:`Loco moco`},{name:`Mix plate`,note:`Teriyaki beef, boneless chicken and mahi with rice and mac salad`,wiki:`Plate lunch`},{name:`Chili dog`,note:`Hot dog topped with the house chili`}],why:`A walk-up plate-lunch stand near Waikīkī since 1961, serving huge portions of island comfort food at local prices.`,tip:`Order at the window and eat at the outdoor tables; a mini plate is plenty for lighter appetites.`,praise:[`Big, filling plates for little money`,`Classic loco moco and mix plates`,`Retro, local atmosphere`],watchOut:`Simple, heavy food, and seating is outdoors only.`,reservation:`walk-in`,reservationNote:`Walk-up window; no bookings`},{id:`waiola-shave-ice`,name:`Waiola Shave Ice`,area:`Mōʻiliʻili`,lat:21.2908,lng:-157.8272,kind:`dessert`,meals:[`lunch`,`dinner`],spend:[5,10],order:[{name:`Rainbow shave ice with ice cream`,note:`Snow-fine ice in three syrups over a scoop of vanilla`,wiki:`Hawaiian shave ice`},{name:`Lilikoʻi and li hing mui shave ice`,note:`Passion fruit and sweet-sour plum syrups`},{name:`Azuki bean and mochi topping`,note:`Sweet red beans and soft rice cakes`}],why:`A long-running neighbourhood shop famous for exceptionally fine, fluffy shave ice soaked with bright tropical syrups.`,tip:`Add a snow cap of condensed milk; a small is bigger than you expect.`,praise:[`Ultra-fine, fluffy ice`,`Wide choice of syrups and toppings`,`Cheap and very refreshing`],reservation:`walk-in`,reservationNote:`Counter service only`},{id:`liliha-bakery`,name:`Liliha Bakery`,area:`Liliha`,lat:21.3228,lng:-157.8536,kind:`cafe`,meals:[`breakfast`,`lunch`,`dinner`],spend:[10,25],order:[{name:`Coco puff`,note:`Chocolate cream puff topped with buttery chantilly frosting`},{name:`Hamburger steak`,note:`Grilled patty in gravy with rice, a diner favourite`},{name:`Butter rolls`,note:`Soft, sweet buttery rolls, grilled at the counter`}],why:`A beloved 1950 bakery and counter diner on Kuakini Street, famous across the islands for its coco puffs and old-school local plates.`,tip:`Grab a counter stool at the original for diner breakfast; boxes of coco puffs travel well, but eat them the same day.`,praise:[`The legendary coco puffs`,`Classic, homey diner breakfasts`,`Good value and fast service`],watchOut:`Waits for counter seats at weekend breakfast.`,reservation:`walk-in`,reservationNote:`No bookings at the counter; bakery orders are takeaway`},{id:`side-street-inn-hopaka`,name:`Side Street Inn`,area:`Ala Moana`,lat:21.2933,lng:-157.8438,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[20,40],order:[{name:`Pan-fried pork chops`,note:`Thin, crisp, garlicky chops piled high, the famous signature`},{name:`Side Street fried rice`,note:`Loaded with lap cheong, bacon and char siu`},{name:`Kalbi short ribs`,note:`Sweet-savoury Korean-style grilled ribs`}],why:`A sports bar near Ala Moana Center that grew into an island institution since 1992, beloved by local chefs for huge, family-style comfort food.`,tip:`Portions are made for sharing, so bring friends and order a few platters; leftovers are expected.`,praise:[`Massive, shareable platters`,`Crispy pork chops and smoky fried rice`,`Fun, local hangout atmosphere`],watchOut:`Plain room and noisy, and a single platter is too much for one or two people.`,reservation:`recommended`,reservationNote:`Call ahead for groups and weekend dinners`},{id:`dukes-waikiki`,name:`Duke's Waikīkī`,area:`Waikīkī`,lat:21.2778,lng:-157.8285,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`],spend:[35,70],order:[{name:`Fresh catch`,note:`Local fish of the day, cooked several ways`},{name:`Hula pie`,note:`Macadamia nut ice cream pie with fudge and whipped cream`},{name:`Huli huli chicken`,note:`Sweet-glazed rotisserie-style chicken, an island classic`}],why:`A beachfront restaurant honouring surf legend Duke Kahanamoku, with surf memorabilia, open-air tables on the sand and live Hawaiian music.`,tip:`Book dinner for sunset; if you cannot, the Barefoot Bar serves food and has live music every afternoon and evening.`,praise:[`Unbeatable beachfront sunset setting`,`The famous hula pie`,`Lively music and aloha spirit`],watchOut:`Crowded and touristy at sunset, with fairly standard food for the price.`,reservation:`recommended`,reservationNote:`Book dinner via its website or by phone; the Barefoot Bar is walk-in`}],dishes:{Poke:{price:[10,22],wiki:`Poke (dish)`},"Plate lunch":{price:[12,20],wiki:`Plate lunch`},"Loco moco":{price:[10,18],wiki:`Loco moco`},"Kalua pig":{price:[12,24],wiki:`Kālua`},"Shave ice":{price:[5,10],wiki:`Hawaiian shave ice`},Malasada:{price:[1.5,3],wiki:`Malassada`}}}},s=e({food:()=>c}),c={"las-vegas":{eateries:[{id:`tacos-el-gordo`,name:`Tacos El Gordo`,area:`North Strip`,lat:36.1325,lng:-115.1637,kind:`street`,meals:[`lunch`,`dinner`,`late`],spend:[10,20],order:[{name:`Adobada taco`,price:4,note:`Chilli-marinated pork shaved from the spit, Tijuana style`,wiki:`Al pastor`},{name:`Carne asada taco`,price:4,note:`Grilled, chopped beef in a small corn tortilla`,wiki:`Carne asada`},{name:`Mulita`,note:`Two tortillas sandwiching cheese and meat, griddled until crisp`}],why:`A Tijuana-style taquería on the Strip, turning out cheap, freshly made street tacos until the small hours.`,tip:`Each meat has its own line; queue at the adobada spit first, and pay at the till afterwards.`,praise:[`Juicy adobada carved straight off the spit`,`Cheap prices for the Strip`,`Open very late`],watchOut:`Separate lines for each meat get long and confusing at peak late-night hours.`,reservation:`walk-in`,reservationNote:`Counter service only; join the line for the meat you want`},{id:`pho-kim-long`,name:`Pho Kim Long`,area:`Chinatown (Spring Mountain Road)`,lat:36.1256,lng:-115.1956,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[12,22],order:[{name:`Pho tai`,price:14,note:`Beef noodle soup with rare steak slices cooked in the hot broth`,wiki:`Pho`},{name:`Bun bo Hue`,price:15,note:`Spicy lemongrass beef and pork noodle soup from central Vietnam`,wiki:`Bún bò Huế`},{name:`Vietnamese iced coffee`,price:5,note:`Strong drip coffee over ice with condensed milk`,wiki:`Vietnamese iced coffee`}],why:`A Chinatown institution for big bowls of pho and Vietnamese rice plates, open almost round the clock.`,tip:`A favourite late-night stop after shows; take a rideshare from the Strip, about ten minutes away.`,praise:[`Generous, comforting bowls of pho`,`Huge menu with something for everyone`,`Open into the early hours`],watchOut:`Service is quick but brisk, and the room is plain.`,reservation:`walk-in`,reservationNote:`No booking needed; tables turn over fast even late at night`},{id:`earl-of-sandwich`,name:`Earl of Sandwich`,area:`The Strip (Planet Hollywood)`,lat:36.1098,lng:-115.1709,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[10,16],order:[{name:`The Original 1762`,price:10,note:`Hot roast beef, cheddar and creamy horseradish on toasted bread`},{name:`Full Montagu`,price:11,note:`Hot sandwich of roast beef, turkey, Swiss cheese and mustard sauce`}],why:`A 24-hour counter inside Planet Hollywood that has long been one of the best cheap eats on the Strip.`,tip:`It is just off the casino floor by the Strip entrance; grab a sandwich for a picnic or a late snack.`,praise:[`Warm sandwiches on freshly toasted bread`,`Good value in an expensive area`,`Open around the clock`],watchOut:`Seating is limited and lines build at lunchtime.`,reservation:`walk-in`,reservationNote:`Order at the counter; no booking needed`},{id:`peppermill`,name:`Peppermill Restaurant & Fireside Lounge`,area:`North Strip`,lat:36.1337,lng:-115.1627,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[22,45],order:[{name:`Breakfast plates and pancakes`,price:20,note:`Oversized American breakfasts served all day`},{name:`Prime rib`,price:40,note:`Slow-roasted rib of beef with jus`,wiki:`Standing rib roast`},{name:`Scorpion cocktail`,price:25,note:`Huge rum punch in a bowl, served in the Fireside Lounge`}],why:`A neon-and-mirrors 24-hour diner open since 1972, with oversized plates and a glowing fire-pit lounge next door.`,tip:`Portions are huge, so share; sit in the Fireside Lounge after dark for drinks by the flaming pool.`,praise:[`Wonderfully retro decor`,`Massive portions`,`Fun late-night lounge`],watchOut:`Prices are high for diner food, and weekend brunch brings waits.`,reservation:`walk-in`,reservationNote:`Generally walk-in; expect a short wait for weekend breakfast`},{id:`lotus-of-siam`,name:`Lotus of Siam`,area:`East of the Strip (Flamingo Road)`,lat:36.1149,lng:-115.1504,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[35,65],order:[{name:`Khao soi`,price:22,note:`Northern Thai curry noodle soup topped with crispy noodles`,wiki:`Khao soi`},{name:`Crispy rice salad`,price:18,note:`Crunchy fried rice tossed with sour pork, chilli, lime and herbs`},{name:`Garlic prawns`,price:30,note:`Prawns fried with lots of crispy garlic and pepper`}],why:`One of America's most celebrated Thai restaurants, famous since the 1990s for northern Thai cooking and a big German wine list.`,tip:`Ask for spice level carefully; "medium" here is hot. The original East Sahara location has also reopened.`,praise:[`Authentic northern Thai specialities`,`Excellent khao soi and crispy rice salad`,`Superb Riesling list to match the spice`],reservation:`recommended`,reservationNote:`Book online for dinner, especially on weekends`},{id:`bacchanal-buffet`,name:`Bacchanal Buffet`,area:`The Strip (Caesars Palace)`,lat:36.1167,lng:-115.1755,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`],spend:[70,110],order:[{name:`Crab legs`,note:`Chilled or steamed snow and king crab legs`,wiki:`Crab`},{name:`Prime rib from the carving station`,note:`Slow-roasted rib of beef carved to order`,wiki:`Standing rib roast`},{name:`Dessert station`,note:`Gelato, soufflés, macarons and individual pastries`}],why:`The Strip's showpiece buffet, with hundreds of dishes cooked in small batches across open kitchens of world cuisines.`,tip:`Weekend brunch and dinner are pricier; arrive early to beat the line, and pace yourself.`,praise:[`Enormous variety across many cuisines`,`Food cooked fresh in small portions`,`Standout dessert section`],watchOut:`Expensive, and queues can be long at peak dinner times.`,reservation:`recommended`,reservationNote:`Reserve a time online to skip most of the line, especially for weekend dinner`},{id:`golden-steer`,name:`Golden Steer Steakhouse`,area:`North Strip (Sahara Avenue)`,lat:36.1439,lng:-115.158,kind:`restaurant`,meals:[`dinner`],spend:[90,160],order:[{name:`Bone-in rib-eye`,price:80,note:`Thick, well-marbled steak on the bone`,wiki:`Rib eye steak`},{name:`Caesar salad made tableside`,price:18,note:`Romaine with anchovy-garlic dressing tossed at your table`,wiki:`Caesar salad`},{name:`Bananas Foster`,note:`Bananas flambéed in rum and butter over ice cream`,wiki:`Bananas Foster`}],why:`A red-velvet steakhouse open since 1958, where the Rat Pack once dined and old-Vegas tableside service lives on.`,tip:`Ask for one of the named celebrity booths when you book; smart-casual dress fits the room.`,praise:[`Big, well-cooked classic steaks`,`Old-Vegas atmosphere and history`,`Theatrical tableside service`],watchOut:`Pricey, and the dated decor is part of the charm, not for everyone.`,reservation:`recommended`,reservationNote:`Book ahead for weekend dinners; request a celebrity booth when reserving`},{id:`hugos-cellar`,name:`Hugo's Cellar`,area:`Downtown (Fremont Street)`,lat:36.1699,lng:-115.1432,kind:`fine`,meals:[`dinner`],spend:[80,140],order:[{name:`Beef Wellington`,note:`Beef fillet wrapped in mushroom duxelles and puff pastry`,wiki:`Beef Wellington`},{name:`Tableside salad cart`,note:`Salad made to order at your table, included with mains`},{name:`Rack of lamb`,note:`Roasted lamb rack, a long-time house classic`,wiki:`Rack of lamb`}],why:`A cosy, candlelit cellar under the Four Queens for over four decades, keeping old-school fine dining rituals alive downtown.`,tip:`Ladies receive a red rose on arrival; mains include the salad cart and a sorbet, so it is better value than it looks.`,praise:[`Warm, attentive old-school service`,`Romantic, intimate cellar room`,`Strong, long-celebrated wine list`],watchOut:`Formal and traditional, with prices to match.`,reservation:`recommended`,reservationNote:`Book ahead, especially Friday and Saturday; dinner only`}],dishes:{"All-you-can-eat buffet":{price:[35,90],wiki:`Buffet`},"Prime rib":{price:[30,60],wiki:`Standing rib roast`},"Steakhouse steak":{price:[55,120],wiki:`Steak`},"Shrimp cocktail":{price:[10,25],wiki:`Prawn cocktail`},"Tacos al pastor":{price:[3,5],wiki:`Al pastor`},Pho:{price:[12,18],wiki:`Pho`}}}},l=e({food:()=>u}),u={"los-angeles":{eateries:[{id:`philippe-the-original`,name:`Philippe the Original`,area:`Chinatown (near Union Station)`,lat:34.05967,lng:-118.23694,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[12,20],order:[{name:`Beef French dip sandwich`,price:14,note:`Sliced roast beef on a French roll dipped in pan juices`,wiki:`French dip`},{name:`Lamb French dip sandwich`,price:16,note:`The same dipped sandwich made with roast lamb`,wiki:`French dip`},{name:`Coleslaw or potato salad`,price:4,note:`Classic deli sides`}],why:`A sawdust-floored counter hall opened in 1908 that claims to have invented the French dip; carvers still dip each roll to order.`,tip:`Order at the counter and ask for it double-dipped; try the fiery house mustard on the tables. A short walk from Union Station.`,praise:[`Cheap, filling sandwiches with old LA character`,`The fiery house mustard`,`Quick counter service even when busy`],watchOut:`Lines get long at lunch and before Dodgers home games.`,reservation:`walk-in`,reservationNote:`No bookings; queue at the counter, order and carry your tray to a table`},{id:`langers-delicatessen`,name:`Langer's Delicatessen`,area:`Westlake (MacArthur Park)`,lat:34.05626,lng:-118.27677,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[25,40],order:[{name:`#19 pastrami sandwich with coleslaw, Swiss and Russian dressing`,note:`Pastrami with coleslaw, Swiss cheese and Russian dressing on rye`},{name:`Hot pastrami on rye`,note:`Hand-cut hot pastrami on double-baked rye`,wiki:`Pastrami on rye`},{name:`Matzo ball soup`,note:`Chicken broth with soft dumplings made from matzo meal`}],why:`A family-run deli open since 1947, famous for hand-cut, peppery pastrami on crisp double-baked rye.`,tip:`Open daytime only and closed Sundays; the Westlake/MacArthur Park Metro station is right across the street.`,praise:[`Tender, peppery, thick-cut pastrami`,`Warm rye with a crackly crust`,`Old-school deli service`],watchOut:`Pricey for a sandwich; the area around MacArthur Park can feel gritty.`,reservation:`walk-in`,reservationNote:`Walk in for a booth or counter seat; waits are short outside the lunch rush`},{id:`guisados-boyle-heights`,name:`Guisados`,area:`Boyle Heights`,lat:34.04815,lng:-118.21148,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[8,15],order:[{name:`Taco sampler of six mini tacos`,price:11,note:`Six small tacos showing off a range of the day's stews`},{name:`Cochinita pibil taco`,price:4,note:`Yucatán-style achiote pork, slow-cooked and topped with pickled onion`,wiki:`Cochinita pibil`},{name:`Steak picado taco`,price:4,note:`Diced steak stewed with peppers, onion and tomato`}],why:`The original shop of a family taqueria that opened in 2010, known for slow-braised Mexican stews on fresh handmade corn tortillas.`,tip:`Get the sampler to try several stews; breakfast tacos are served in the morning. Other branches include Downtown and Echo Park.`,praise:[`Rich, slow-cooked stews`,`Soft, fresh handmade tortillas`,`The sampler lets you try many fillings`],reservation:`walk-in`,reservationNote:`Order at the counter and grab a table; no bookings`},{id:`leos-tacos-truck-la-brea`,name:`Leo's Tacos Truck`,area:`Mid-City (La Brea & Venice)`,lat:34.04626,lng:-118.34593,kind:`street`,meals:[`lunch`,`dinner`,`late`],spend:[6,12],order:[{name:`Tacos al pastor`,price:3,note:`Spit-roasted marinated pork with pineapple on small corn tortillas`,wiki:`Al pastor`},{name:`Carne asada taco`,price:3,note:`Grilled chopped beef on small corn tortillas`}],why:`A taco truck parked in a gas-station lot since 2010, where al pastor is shaved off a flaming trompo and topped with a slice of pineapple.`,tip:`Busiest late at night; order at the window, then help yourself to salsas and grilled onions.`,praise:[`Al pastor carved straight off the spit`,`Very cheap tacos`,`Fun late-night scene`],watchOut:`Outdoor, standing only, and queues get long late at night.`,reservation:`walk-in`,reservationNote:`Taco truck: queue at the window, no bookings`},{id:`pinks-hot-dogs`,name:`Pink's Hot Dogs`,area:`Hollywood (La Brea Ave)`,lat:34.08391,lng:-118.34428,kind:`street`,meals:[`lunch`,`dinner`,`late`],spend:[8,15],order:[{name:`Chili cheese dog`,price:8,note:`Hot dog topped with meat chili and melted cheese`,wiki:`Chili dog`},{name:`Chili fries`,price:7,note:`Fries covered in chili`}],why:`A family-run hot dog stand on La Brea since the 1940s, a Hollywood fixture for chili dogs named after film and TV stars.`,tip:`Open late, especially at weekends; expect a queue on the sidewalk at peak times.`,praise:[`A fun Hollywood landmark`,`Snappy dogs smothered in chili`,`Big menu of celebrity-named hot dogs`],watchOut:`Touristy and pricey for hot dogs, with a long wait at busy times.`,reservation:`walk-in`,reservationNote:`Order at the stand; no bookings, so go off-peak to skip the queue`},{id:`republique`,name:`République`,area:`Mid-Wilshire (La Brea Ave)`,lat:34.06416,lng:-118.34377,kind:`cafe`,meals:[`breakfast`,`lunch`,`dinner`],spend:[25,70],order:[{name:`Pastries from the bakery counter, such as the kouign-amann`,price:6,note:`Buttery Breton pastry with caramelised, crackly layers`,wiki:`Kouign-amann`},{name:`Shakshuka`,price:22,note:`Eggs poached in a spiced tomato and pepper sauce`,wiki:`Shakshouka`}],why:`A French bakery-café and bistro by chefs Walter and Margarita Manzke, set in a striking 1920s building with an in-house bakery.`,tip:`Daytime is counter service, so order before you sit; dinner is more formal and worth reserving.`,praise:[`Excellent pastries and breads`,`Gorgeous high-ceilinged room`,`Strong brunch menu`],watchOut:`Weekend brunch queues are long and prices are high.`,reservation:`recommended`,reservationNote:`Daytime is walk-in counter service; book dinner a week or so ahead`},{id:`parks-bbq`,name:`Park's BBQ`,area:`Koreatown`,lat:34.054,lng:-118.29204,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[60,100],order:[{name:`Galbi (marinated beef short rib)`,note:`Soy-marinated beef short rib grilled at the table`,wiki:`Galbi`},{name:`Pork belly`,note:`Thick slices of pork belly grilled at the table`,wiki:`Samgyeopsal`},{name:`Stone pot bibimbap`,note:`Rice, vegetables and egg in a sizzling stone bowl, crisp at the bottom`,wiki:`Bibimbap`}],why:`A Koreatown grill house run by chef Jenee Kim since 2003, known for high-grade beef cooked at the table with plentiful banchan.`,tip:`Book a few days ahead for dinner; lunch is easier to walk into.`,praise:[`High-quality, well-marbled beef`,`Generous spread of banchan side dishes`,`Staff often help grill at the table`],watchOut:`Expensive for Korean barbecue, and dinner waits are long without a booking.`,reservation:`recommended`,reservationNote:`Reserve for dinner, especially weekends; walk-ins usually fine at lunch`},{id:`gjusta`,name:`Gjusta`,area:`Venice`,lat:33.99527,lng:-118.47458,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[20,40],order:[{name:`Smoked fish plate or lox sandwich`,note:`House-smoked fish such as salmon with bread and accompaniments`},{name:`Croissant or other pastry`,note:`Flaky laminated pastries from the in-house bakery`,wiki:`Croissant`}],why:`A Venice bakery and deli from the team behind Gjelina, with a long counter of breads, pastries, smoked fish and sandwiches.`,tip:`Take a numbered ticket when you arrive; pastries sell out by midday, and it closes in the afternoon.`,praise:[`Huge, tempting counter of breads and pastries`,`Excellent house-smoked fish`,`Laid-back Venice feel`],watchOut:`Chaotic ordering, limited seating and high prices.`,reservation:`walk-in`,reservationNote:`No bookings; take a number, order at the counter and hunt for a seat`}],dishes:{"Tacos al pastor":{price:[2,5],wiki:`Al pastor`},"French dip sandwich":{price:[12,20],wiki:`French dip`},"Pastrami sandwich":{price:[18,30],wiki:`Pastrami`},"Korean barbecue":{price:[35,75],wiki:`Korean barbecue`},"Chili dog":{price:[6,10],wiki:`Chili dog`},"California roll":{price:[8,15],wiki:`California roll`}}}},d=e({food:()=>f}),f={"washington-dc":{eateries:[{id:`bens-chili-bowl`,name:`Ben's Chili Bowl`,area:`U Street`,lat:38.917,lng:-77.0288,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[8,16],order:[{name:`Chili half-smoke`,price:9,note:`Smoky pork-and-beef sausage with chili, mustard and onions`,wiki:`Half-smoke`},{name:`Chili cheese fries`,price:7,note:`Fries smothered in the house chili and melted cheese`}],why:`A U Street landmark opened in 1958 that stayed open through the 1968 unrest and is the classic place for the city's own half-smoke.`,tip:`Order at the counter; open late on weekends, when the after-club crowd piles in.`,praise:[`The definitive D.C. half-smoke`,`Rich, meaty house chili`,`A real slice of U Street history`],watchOut:`Cramped, touristy and busy late at night.`,reservation:`walk-in`,reservationNote:`Counter service, no bookings; grab a booth if one frees up`},{id:`market-lunch-eastern-market`,name:`The Market Lunch`,area:`Capitol Hill`,lat:38.8866,lng:-76.9964,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[10,25],order:[{name:`Blueberry buckwheat pancakes`,price:9,note:`Known locally as bluebucks: buckwheat pancakes packed with blueberries`},{name:`Crab cake sandwich`,price:20,note:`A lump crab cake on bread with tartar sauce`,wiki:`Crab cake`}],why:`A counter inside Eastern Market serving pancakes and crab cakes since 1978, a weekend ritual for Capitol Hill locals.`,tip:`Closed Mondays; know your order before you reach the front, as the line moves briskly. Bluebucks are served at breakfast only.`,praise:[`Fluffy, fruit-packed blueberry pancakes`,`Chunky crab cakes at a fair price`,`Lively market atmosphere`],watchOut:`Weekend lines are long and seating is limited to a counter and a few tables.`,reservation:`walk-in`,reservationNote:`No bookings; queue at the counter, ideally on a weekday`},{id:`old-ebbitt-grill`,name:`Old Ebbitt Grill`,area:`Downtown`,lat:38.898,lng:-77.0333,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[35,70],order:[{name:`Raw-bar oysters`,note:`A changing selection of East Coast oysters on the half shell`,wiki:`Eastern oyster`},{name:`Crab cakes`,note:`Jumbo lump Maryland-style crab cakes`,wiki:`Crab cake`}],why:`A Victorian-style saloon a block from the White House, tracing its roots to 1856 and buzzing with politicos, tourists and oyster lovers.`,tip:`Late-night oyster happy hour at the raw bar is the best deal; dress is smart casual.`,praise:[`Fresh, well-shucked oysters`,`Grand old-Washington setting`,`Open long hours, all week`],watchOut:`Touristy, loud and often very busy.`,reservation:`recommended`,reservationNote:`Book ahead for dinner and weekend brunch; the bar is walk-in`},{id:`rasika-penn-quarter`,name:`Rasika`,area:`Penn Quarter`,lat:38.8946,lng:-77.0215,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,90],order:[{name:`Palak chaat`,note:`Crispy fried baby spinach with yoghurt, tamarind and date chutney`,wiki:`Chaat`},{name:`Black cod`,note:`Fish glazed with honey, dill and star anise`},{name:`Chicken tikka masala`,note:`Tandoor-grilled chicken in a creamy spiced tomato sauce`,wiki:`Chicken tikka masala`}],why:`Modern Indian cooking by chef Vikram Sunderam since 2005, a fixture on lists of the city's best restaurants for two decades.`,tip:`The palak chaat is a must; the Penn Quarter original is near the Archives and Gallery Place Metro stations.`,praise:[`Inventive, perfectly spiced dishes`,`The famous crispy spinach chaat`,`Polished, attentive service`],watchOut:`Prime dinner tables are hard to get at short notice.`,reservation:`recommended`,reservationNote:`Book on the restaurant's website a couple of weeks ahead for dinner; lunch is easier`},{id:`jaleo-penn-quarter`,name:`Jaleo`,area:`Penn Quarter`,lat:38.8949,lng:-77.0217,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[40,70],order:[{name:`Pan con tomate with jamón ibérico`,note:`Toasted bread rubbed with tomato, topped with cured Iberian ham`,wiki:`Pa amb tomàquet`},{name:`Gambas al ajillo`,note:`Shrimp sizzled in olive oil with garlic and chilli`},{name:`Paella`,note:`Saffron rice from the wood-fired paella pan, to share`,wiki:`Paella`}],why:`José Andrés's first restaurant, opened in 1993, which made Spanish tapas a D.C. staple and launched his career.`,tip:`Order several tapas to share; the paellas take a while, so order early.`,praise:[`Authentic, well-made tapas`,`Fun and lively for groups`,`Good Spanish wine list`],watchOut:`Small plates add up quickly.`,reservation:`recommended`,reservationNote:`Reserve online for dinner, especially before shows at nearby theatres`},{id:`le-diplomate`,name:`Le Diplomate`,area:`Logan Circle`,lat:38.9115,lng:-77.0319,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`],spend:[50,90],order:[{name:`Steak frites`,note:`Grilled steak with herb butter and a heap of thin fries`,wiki:`Steak frites`},{name:`French onion soup`,note:`Beef-onion broth under a crust of bubbling Gruyère`,wiki:`French onion soup`}],why:`A Parisian-style brasserie on 14th Street since 2013, with zinc bar, mosaic floors and a sunny sidewalk terrace.`,tip:`The bread basket from its own bakery is a highlight; weekend brunch is the hardest booking.`,praise:[`Convincing Parisian brasserie atmosphere`,`Excellent bread and classic French dishes`,`Lovely sidewalk terrace`],watchOut:`Loud and crowded, with tables close together.`,reservation:`recommended`,reservationNote:`Book 2 to 4 weeks ahead for dinner or brunch; bar and terrace seats are walk-in`},{id:`ethiopic`,name:`Ethiopic`,area:`H Street NE`,lat:38.9001,lng:-76.9992,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[25,45],order:[{name:`Vegetarian sampler`,note:`Lentil, split-pea, greens and cabbage stews on injera`,wiki:`Injera`},{name:`Awaze tibs`,note:`Sautéed beef or lamb in a spicy berbere pepper sauce`},{name:`Doro wat`,note:`Chicken simmered in a deep red berbere stew with a boiled egg`,wiki:`Wat (food)`}],why:`A stylish, family-run Ethiopian restaurant on the H Street corridor since 2013, known for carefully made stews and warm service.`,tip:`Lunch is served Friday to Sunday only; eat with your hands using torn injera.`,praise:[`Bright, complex spice blends`,`A generous, varied vegetarian sampler`,`Calm, attractive room`],watchOut:`A fixed service charge is added to dine-in bills.`,reservation:`recommended`,reservationNote:`Book for Friday and Saturday nights; weeknights are usually fine as a walk-in`},{id:`martins-tavern`,name:`Martin's Tavern`,area:`Georgetown`,lat:38.9064,lng:-77.063,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[25,50],order:[{name:`Hot Brown`,note:`Open-faced turkey sandwich baked with Mornay sauce and bacon`,wiki:`Hot Brown`},{name:`Crab cake platter`,note:`Maryland-style crab cakes with sides`,wiki:`Crab cake`}],why:`A wood-panelled Georgetown tavern run by the same family since 1933, where every US president from Truman to George W. Bush has dined.`,tip:`Ask about the booth where John F. Kennedy is said to have proposed to Jacqueline Bouvier.`,praise:[`Cosy, history-filled dining room`,`Hearty American comfort food`,`Friendly, old-fashioned service`],reservation:`recommended`,reservationNote:`Book for dinner and weekend brunch; weekday lunch is easy to walk into`}],dishes:{"Half-smoke":{price:[7,12],wiki:`Half-smoke`},"Maryland crab cake":{price:[18,40],wiki:`Crab cake`},"Mumbo sauce wings":{price:[8,15],wiki:`Mumbo sauce`},"Ethiopian injera platter":{price:[15,30],wiki:`Injera`},"Jumbo slice":{price:[5,9],wiki:`Jumbo slice`},"Chesapeake oysters":{price:[15,30],wiki:`Eastern oyster`}}}},p=e({food:()=>m}),m={"new-york":{eateries:[{id:`katzs-delicatessen`,name:`Katz's Delicatessen`,area:`Lower East Side`,lat:40.72229,lng:-73.98743,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[30,45],order:[{name:`Pastrami on rye`,price:29,note:`Hand-sliced hot pastrami piled on rye bread with mustard`,wiki:`Pastrami on rye`},{name:`Matzo ball soup`,price:10,note:`Chicken broth with soft dumplings made from matzo meal`},{name:`Hot dog`,price:7,note:`All-beef frank in a bun with mustard and sauerkraut`,wiki:`Hot dog`}],why:`A Lower East Side deli founded in 1888, famous for hand-carved pastrami sandwiches piled high on rye.`,tip:`Hold on to your ticket at the door; lose it and you pay a fee. Tip the carver for a taste while you wait.`,praise:[`Pastrami is juicy, smoky and carved thick by hand`,`Sandwiches are huge and easily shared between two`,`Old-school deli bustle and a long slice of New York history`],watchOut:`Pricey for a sandwich and very busy with tourists at peak times.`,reservation:`walk-in`,reservationNote:`No bookings; take a ticket at the door and order at the counter or wait for a table`},{id:`russ-and-daughters`,name:`Russ & Daughters`,area:`Lower East Side`,lat:40.72267,lng:-73.98824,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[15,30],order:[{name:`Bagel with lox and cream cheese`,price:18,note:`Bagel spread with cream cheese and topped with thin-sliced cured salmon`,wiki:`Bagel and cream cheese`},{name:`Classic Super Heebster bagel`,price:20,note:`House bagel with whitefish and salmon salad, horseradish cream cheese and roe`}],why:`An appetizing shop on East Houston Street since 1914, run by the same family for four generations, known for smoked fish and bagels.`,tip:`Take a number at the counter; for a sit-down meal use the family's café on Orchard Street.`,praise:[`Silky smoked salmon sliced by hand to order`,`Knowledgeable counter staff happy to offer tastes`,`A real piece of old Lower East Side food history`],watchOut:`Weekend queues can be long and prices are high for a bagel.`,reservation:`walk-in`,reservationNote:`No bookings at the shop; pull a number and wait to be called`},{id:`joes-pizza-carmine`,name:`Joe's Pizza`,area:`Greenwich Village`,lat:40.73058,lng:-74.00213,kind:`street`,meals:[`lunch`,`dinner`,`late`],spend:[5,12],order:[{name:`Plain cheese slice`,price:4,note:`Thin New York slice with tomato sauce and mozzarella`,wiki:`New York–style pizza`},{name:`Pepperoni slice`,price:5,note:`Cheese slice topped with crisp-edged pepperoni`}],why:`A Village slice joint opened in 1975 by Joe Pozzuoli, a benchmark for thin, foldable New York-style pizza by the slice.`,tip:`Standing room only; the line moves fast and it stays open past midnight.`,praise:[`Classic thin, foldable crust with a good sauce-to-cheese balance`,`Cheap, fast and open late`,`Pies turn over quickly so slices come out hot`],reservation:`walk-in`,reservationNote:`No bookings; order slices at the counter and eat standing or on the go`},{id:`the-halal-guys-53rd`,name:`The Halal Guys`,area:`Midtown (53rd St & 6th Ave)`,lat:40.76185,lng:-73.9791,kind:`street`,meals:[`lunch`,`dinner`,`late`],spend:[10,15],order:[{name:`Chicken and gyro over rice`,price:12,note:`Chopped chicken and gyro meat over yellow rice with white and hot sauce`},{name:`Falafel platter`,price:11,note:`Fried chickpea fritters over rice with salad, pita and sauces`,wiki:`Falafel`}],why:`The original Midtown food cart that made chicken over rice with white sauce a New York staple, serving since the 1990s.`,tip:`Go easy on the red hot sauce. The cart on the southeast corner is the original.`,praise:[`Big portions for the price`,`The tangy white sauce is the signature`,`Quick, filling street food late into the night`],watchOut:`Long lines at lunch and on weekend nights; look-alike carts nearby use similar branding.`,reservation:`walk-in`,reservationNote:`Street cart: just join the line and order at the window`},{id:`juniors-brooklyn`,name:`Junior's Restaurant`,area:`Downtown Brooklyn (Flatbush Ave)`,lat:40.6904,lng:-73.9817,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[20,40],order:[{name:`Original New York cheesecake slice`,price:10,note:`Dense, creamy baked cream-cheese cake on a thin sponge base`,wiki:`Cheesecake`},{name:`Pastrami Reuben`,price:25,note:`Grilled rye with pastrami, Swiss cheese, sauerkraut and Russian dressing`,wiki:`Reuben sandwich`}],why:`A Brooklyn diner open since 1950 whose rich, creamy cheesecake became one of the city's best-known desserts.`,tip:`Whole cheesecakes can be bought at the bakery counter to take away; branches also near Times Square.`,praise:[`Rich, dense yet creamy cheesecake`,`Classic diner feel with big menus and portions`,`Easy place to pick up a whole cheesecake to take home`],watchOut:`The savoury diner food is pricey for what it is; the cheesecake is the main draw.`,reservation:`walk-in`,reservationNote:`Walk in and wait for a table; for cheesecake to go, use the bakery counter`},{id:`chelsea-market`,name:`Chelsea Market`,area:`Chelsea / Meatpacking District`,lat:40.7424,lng:-74.0061,kind:`market`,meals:[`breakfast`,`lunch`,`dinner`],spend:[12,30],order:[{name:`Tacos from the market stalls`,price:6,note:`Small corn-tortilla tacos with fillings like adobada or carne asada`,wiki:`Taco`},{name:`Lobster roll`,price:32,note:`Chunks of lobster meat in a buttered, toasted split-top bun`,wiki:`Lobster roll`}],why:`An indoor food hall in the former Nabisco factory, with dozens of vendors and an easy stop before or after the High Line.`,tip:`Weekday mornings are calmest; weekends get very crowded.`,praise:[`Huge variety of food under one roof`,`Handy stop right by the High Line`,`Atmospheric old brick factory building`],watchOut:`Crowded and touristy, and seating is hard to find at lunchtime.`,reservation:`walk-in`,reservationNote:`Food hall: order at each stall; no booking needed`},{id:`levain-bakery-74th`,name:`Levain Bakery`,area:`Upper West Side (74th St)`,lat:40.7799,lng:-73.9803,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[6,12],order:[{name:`Chocolate chip walnut cookie`,price:6,note:`Thick six-ounce cookie packed with chocolate chips and walnuts`,wiki:`Chocolate chip cookie`},{name:`Dark chocolate peanut butter chip cookie`,price:6,note:`Dark chocolate cookie dough studded with peanut butter chips`}],why:`The tiny basement bakery that started the craze for huge, gooey six-ounce cookies in 1995, near Central Park West.`,tip:`Takeaway only from a small shop; a cookie easily feeds two.`,praise:[`Enormous, thick cookies with a gooey middle`,`Crisp outside, almost molten inside when warm`,`A sweet stop after a walk in Central Park`],watchOut:`Queues spill onto the sidewalk at weekends, and the cookies are very rich.`,reservation:`walk-in`,reservationNote:`Takeaway counter only; queue on the sidewalk and order inside`},{id:`gramercy-tavern`,name:`Gramercy Tavern`,area:`Flatiron / Gramercy`,lat:40.73855,lng:-73.98848,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[60,150],order:[{name:`Tavern menu (walk-in front room)`,price:60,note:`A la carte dishes in the front bar room, no booking needed`},{name:`Seasonal tasting menu`,price:160,note:`Multi-course seasonal menu served in the main dining room`}],why:`A Danny Meyer American restaurant open since 1994, known for warm hospitality and seasonal, market-driven cooking.`,tip:`The front Tavern room takes walk-ins and is the more affordable choice; book the dining room well ahead.`,praise:[`Warm, attentive and unstuffy service`,`Seasonal American cooking with standout vegetables`,`Handsome, flower-filled rooms`],watchOut:`Expensive in the dining room, and prime-time reservations go fast.`,reservation:`recommended`,reservationNote:`Reserve the dining room weeks ahead for dinner; the front Tavern room is walk-in only`}],dishes:{"New York-style pizza":{price:[3,6],wiki:`New York–style pizza`},"Bagel with lox and schmear":{price:[10,20],wiki:`Bagel and cream cheese`},"Pastrami on rye":{price:[20,30],wiki:`Pastrami on rye`},"New York cheesecake":{price:[7,12],wiki:`Cheesecake`},"Halal cart chicken over rice":{price:[9,13],wiki:`Halal cart`},"Black-and-white cookie":{price:[3,5],wiki:`Black and white cookie`}}},"san-francisco":{eateries:[{id:`tartine-bakery`,name:`Tartine Bakery`,area:`Mission District (Guerrero St)`,lat:37.7614,lng:-122.4241,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[10,25],order:[{name:`Morning bun`,price:6,note:`Croissant dough rolled with cinnamon, orange and sugar, baked till sticky`},{name:`Croque monsieur`,price:18,note:`Toasted ham and cheese sandwich topped with béchamel`,wiki:`Croque monsieur`},{name:`Country loaf (sourdough)`,price:14,note:`Dark-crusted, open-crumbed sourdough loaf`,wiki:`Sourdough`}],why:`The Mission bakery opened in 2002 that helped define modern San Francisco sourdough and pastry.`,tip:`Lines form at opening and on weekends; bread comes out in the afternoon.`,praise:[`Flaky, deeply caramelised pastries`,`The morning bun is a cult favourite`,`Excellent sourdough with a dark, crackly crust`],watchOut:`Long lines, little seating and prices on the high side.`,reservation:`walk-in`,reservationNote:`No bookings; join the line and order at the counter`},{id:`la-taqueria`,name:`La Taqueria`,area:`Mission District (Mission St)`,lat:37.7509,lng:-122.4181,kind:`casual`,meals:[`lunch`,`dinner`],spend:[12,20],order:[{name:`Carnitas burrito, dorado style`,price:14,note:`Flour tortilla of braised pork, beans and salsa, griddled until crisp`,wiki:`Mission burrito`},{name:`Carne asada tacos`,price:6,note:`Grilled chopped beef in soft corn tortillas with salsa`}],why:`A Mission taqueria open since 1973, a classic for rice-free Mission burritos and crisp griddled "dorado" burritos.`,tip:`The burritos have no rice by default; lines move quickly.`,praise:[`Meaty, juicy burritos with no rice filler`,`The crisp, griddled dorado burrito is a favourite`,`Excellent carnitas and fresh salsas`],watchOut:`Busy at lunch with limited seating.`,reservation:`walk-in`,reservationNote:`Order at the counter, then grab any free table; no bookings`},{id:`ferry-building-marketplace`,name:`Ferry Building Marketplace`,area:`Embarcadero`,lat:37.7956,lng:-122.3937,kind:`market`,meals:[`breakfast`,`lunch`],spend:[12,30],order:[{name:`Oysters at the Hog Island bar`,price:4,note:`Raw local oysters shucked to order at the oyster bar`},{name:`Sourdough and cheese from the market shops`,price:15,note:`Bay Area bakery bread with local cheeses from the market shops`}],why:`The restored 1898 ferry terminal on the waterfront, now a food hall of Bay Area bakers, cheesemakers, oyster bars and cafés.`,tip:`Visit on Tuesday, Thursday or Saturday morning when the farmers market sets up outside.`,praise:[`Excellent local produce and artisan food stalls`,`Waterfront setting with Bay views`,`Oysters, bread and cheese are standouts`],watchOut:`Crowded at weekends and prices are premium.`,reservation:`walk-in`,reservationNote:`Market hall: order at each shop or stall; no booking needed`},{id:`swan-oyster-depot`,name:`Swan Oyster Depot`,area:`Nob Hill / Polk Gulch`,lat:37.7906,lng:-122.4208,kind:`casual`,meals:[`lunch`],spend:[40,80],order:[{name:`Dungeness crab (seasonal)`,price:60,note:`Cold cracked local crab served with sauce`,wiki:`Dungeness crab`},{name:`Oysters on the half shell`,price:4,note:`Raw oysters opened and served on the shell with lemon`},{name:`Clam chowder`,price:10,note:`Creamy New England-style soup of clams and potatoes`,wiki:`Clam chowder`}],why:`A counter-only seafood shop on Polk Street dating from 1912, serving crab, oysters and chowder at a long marble bar.`,tip:`Lunch hours only, closed Sundays, around 20 stools and long waits: arrive before opening.`,praise:[`Very fresh seafood served simply`,`Friendly, joking staff behind the counter`,`Old-school marble counter charm`],watchOut:`Cash only, waits can top an hour, and crab is pricey.`,reservation:`walk-in`,reservationNote:`No reservations; queue outside for a counter stool`},{id:`sotto-mare`,name:`Sotto Mare`,area:`North Beach`,lat:37.7997,lng:-122.4075,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[35,60],order:[{name:`Crab cioppino (for two)`,price:70,note:`Tomato and wine seafood stew of crab, clams, mussels, prawns and fish`,wiki:`Cioppino`},{name:`Clam chowder`,price:12,note:`Creamy soup of clams and potatoes`,wiki:`Clam chowder`}],why:`A North Beach Italian seafood restaurant open since 2007, best known for a huge, spicy cioppino.`,tip:`Busy on Friday and Saturday nights; book ahead and share the cioppino.`,praise:[`Huge cioppino loaded with crab and shellfish`,`Fun, lively North Beach atmosphere`,`Generous portions made for sharing`],watchOut:`Small, noisy and cramped, with waits at peak times.`,reservation:`recommended`,reservationNote:`Book for Friday and Saturday dinner; weekday lunch is usually fine to walk in`},{id:`good-mong-kok-bakery`,name:`Good Mong Kok Bakery`,area:`Chinatown (Stockton St)`,lat:37.7953,lng:-122.408,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[5,12],order:[{name:`Baked char siu bao`,price:2,note:`Glazed baked bun filled with sweet barbecue pork`,wiki:`Char siu bao`},{name:`Har gow (shrimp dumplings)`,price:4,note:`Translucent wheat-starch dumplings filled with shrimp`,wiki:`Har gow`},{name:`Siu mai`,price:4,note:`Open-topped pork and shrimp dumplings`,wiki:`Shumai`}],why:`A no-frills Chinatown takeaway counter selling dim sum by the piece, popular with locals for its cheap, fresh dumplings and buns.`,tip:`Cash only and takeaway only; eat in nearby Portsmouth Square.`,praise:[`Very cheap dim sum`,`Dumplings and buns fresh from the steamers`,`Fast takeaway service`],watchOut:`Queues at lunchtime and a cramped, hectic shop with no seating.`,reservation:`walk-in`,reservationNote:`Takeaway counter: point at what you want and pay; no bookings`},{id:`buena-vista-cafe`,name:`The Buena Vista`,area:`Fisherman's Wharf (Hyde St)`,lat:37.8065,lng:-122.4207,kind:`bar`,meals:[`breakfast`,`lunch`,`late`],spend:[15,30],order:[{name:`Irish coffee`,price:13,note:`Hot coffee with Irish whiskey and sugar under a layer of cream`,wiki:`Irish coffee`},{name:`Eggs Benedict`,price:20,note:`Poached eggs and ham on an English muffin with hollandaise`,wiki:`Eggs Benedict`}],why:`A corner bar by the Hyde Street cable car turnaround that has served Irish coffee since 1952 and is said to have introduced it to America.`,tip:`Grab a stool at the bar to watch rows of Irish coffees being made at once.`,praise:[`Classic Irish coffee made with theatrical speed`,`Historic, convivial old bar`,`Handy before or after the cable car`],watchOut:`Crowded with tourists; the food is secondary to the drinks.`,reservation:`walk-in`,reservationNote:`Walk in and wait for a bar stool or table; no booking needed`},{id:`zuni-cafe`,name:`Zuni Café`,area:`Hayes Valley (Market St)`,lat:37.7736,lng:-122.4215,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,90],order:[{name:`Roast chicken with bread salad (for two)`,price:70,note:`Brick-oven roast chicken over warm bread salad with currants and pine nuts`},{name:`Caesar salad`,price:18,note:`Romaine with anchovy dressing, croutons and Parmesan`,wiki:`Caesar salad`},{name:`Shoestring fries`,price:10,note:`Thin, crisp fried potatoes`,wiki:`French fries`}],why:`A Market Street institution since 1979, famous for its brick-oven roast chicken with warm bread salad.`,tip:`Order the chicken as soon as you sit down: it takes about an hour to roast.`,praise:[`Juicy, crisp-skinned roast chicken`,`Bread salad that soaks up the chicken juices`,`Lively, light-filled room with a long copper bar`],watchOut:`Pricey, and dinner without a booking can mean a long wait.`,reservation:`recommended`,reservationNote:`Reserve for dinner a week or so ahead; the bar can work for walk-ins`}],dishes:{"Sourdough bread":{price:[5,14],wiki:`Sourdough`},"Mission burrito":{price:[11,16],wiki:`Mission burrito`},"Dungeness crab":{price:[40,70],wiki:`Dungeness crab`},Cioppino:{price:[35,60],wiki:`Cioppino`},"Dim sum":{price:[4,10],wiki:`Dim sum`},"Irish coffee at the Buena Vista":{price:[12,14],wiki:`Irish coffee`}}}};export{a,s as i,d as n,r as o,l as r,t as s,p as t};